CREATE TABLE IF NOT EXISTS labour_weight_consumptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, labour_weight_id BIGINT UNSIGNED NOT NULL, production_entry_id BIGINT NOT NULL, dipping_qty INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_labour_consumption_production (production_entry_id), KEY idx_labour_consumption_labour (labour_weight_id), CONSTRAINT fk_labour_consumption_weight FOREIGN KEY (labour_weight_id) REFERENCES labour_weight_entries(id)) ENGINE=InnoDB;
